spec.expr:
count by (generation) (
  max by (generation, instance_id, collection_id) (
    label_replace(
      mz_dataflow_wallclock_lag_seconds{
        materialize_cloud_organization_name=~"$environmentNameList",
        pod=~".*-(environmentd|gen)-(${mzGenerationList:regex})-[0-9]+",
        instance_id=~"$mzClusterList",
        instance_id!="",
        quantile="1"
      },
      "generation", "$1", "pod", ".*-(?:environmentd|gen)-([0-9]+)-[0-9]+"
    )
  )
)

